subagents.output_schema_json:
{
  "additionalProperties": false,
  "properties": {
    "comps_benchmarks": {
      "description": "Sector-level comps: median PE, EV/EBITDA, growth rates",
      "properties": {
        "median_ev_ebitda": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "median_pe": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "median_revenue_growth": {
          "maxLength": 32,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        }
      },
      "type": "object"
    },
    "sector": {
      "maxLength": 64,
      "pattern": "^[A-Za-z0-9 _-]+$",
      "type": "string"
    },
    "sector_outlook": {
      "enum": [
        "overweight",
        "neutral",
        "underweight"
      ],
      "type": "string"
    },
    "sensitivity_matrix": {
      "description": "Growth vs discount rate sensitivity table",
      "type": "object"
    },
    "tool_calls": {
      "items": {
        "properties": {
          "count": {
            "type": "integer"
          },
          "name": {
            "maxLength": 64,
            "pattern": "^[A-Za-z0-9_-]+$",
            "type": "string"
          }
        },
        "type": "object"
      },
      "maxItems": 200,
      "type": "array"
    },
    "top_picks": {
      "items": {
        "properties": {
          "dcf_value": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "recommendation": {
            "enum": [
              "buy",
              "hold",
              "sell",
              "outperform",
              "underperform",
              "no_recommendation"
            ],
            "type": "string"
          },
          "target_price": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "ticker": {
            "maxLength": 64,
            "pattern": "^[A-Za-z0-9._-]+$",
            "type": "string"
          },
          "wacc": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          }
        },
        "type": "object"
      },
      "maxItems": 20,
      "type": "array"
    },
    "traceability_table": {
      "items": {
        "properties": {
          "metric": {
            "maxLength": 200,
            "type": "string"
          },
          "source": {
            "maxLength": 200,
            "type": "string"
          },
          "value": {
            "maxLength": 200,
            "type": "string"
          }
        },
        "type": "object"
      },
      "maxItems": 500,
      "type": "array"
    }
  },
  "required": [
    "sector",
    "top_picks",
    "comps_benchmarks",
    "sector_outlook",
    "tool_calls"
  ],
  "type": "object"
}

{
  "additionalProperties": false,
  "properties": {
    "as_of_date": {
      "maxLength": 10,
      "pattern": "^[0-9-]{1,10}$",
      "type": "string"
    },
    "constituents": {
      "items": {
        "properties": {
          "ev_ebitda": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "market_cap": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "name": {
            "maxLength": 128,
            "type": "string"
          },
          "pe_ratio": {
            "maxLength": 32,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "ticker": {
            "maxLength": 64,
            "pattern": "^[A-Za-z0-9._-]+$",
            "type": "string"
          }
        },
        "type": "object"
      },
      "maxItems": 50,
      "type": "array"
    },
    "data_source": {
      "enum": [
        "fmp",
        "data",
        "mixed"
      ],
      "maxLength": 16,
      "type": "string"
    },
    "macro_series": {
      "description": "FRED macro series (rates, CPI, PMI)",
      "type": "object"
    },
    "sector": {
      "maxLength": 64,
      "pattern": "^[A-Za-z0-9 _-]+$",
      "type": "string"
    },
    "snapshot": {
      "description": "Sector constituents, fundamentals, macro series, and news keyed by data type",
      "type": "object"
    }
  },
  "required": [
    "sector",
    "as_of_date",
    "snapshot",
    "constituents"
  ],
  "type": "object"
}
